UPDATE t_alert_data_contract SET schema_version='subject-fingerprint-v1',source_system='t_feedback_identity',freshness_seconds=300,completeness_threshold=.990000
WHERE contract_code IN ('contact_fingerprint','subject_fingerprint') AND contract_status='DRAFT';
UPDATE t_alert_data_contract SET schema_version='cluster-lifecycle-v1',source_system='t_cluster+t_cluster_link',freshness_seconds=300,completeness_threshold=.990000
WHERE contract_code IN ('cluster_id','cluster_resolution','cluster_lifecycle','last_occurrence') AND contract_status='DRAFT';

